/* Minimal Node.js-like event append + projection */
const eventStore = new Map();
const bus = { subs: {}, publish(e){ (this.subs[e.type]||[]).forEach(h=>h(e)) }, subscribe(t,h){ this.subs[t]=this.subs[t]||[]; this.subs[t].push(h) } };

async function appendEvent(streamId, event){
  eventStore.set(streamId, (eventStore.get(streamId)||[]).concat(event));
  return true;
}

async function handlePlaceOrder(cmd){
  if (!cmd.items.length) throw new Error('empty');
  const evt = { type: 'OrderPlaced', data: { orderId: cmd.orderId, items: cmd.items } };
  await appendEvent(cmd.orderId, evt);
  bus.publish(evt);
}

bus.subscribe('OrderPlaced', evt => {
  // naive projection stored in-memory
  const summaries = globalThis.orderSummaries = globalThis.orderSummaries||{};
  summaries[evt.data.orderId] = { status: 'Placed', items: evt.data.items };
});
